<?php require_once dirname(__DIR__,2).'/bootstrap.php';$me=current_user();$id=(int)($_GET['user_id']??($me['id']??0));if(!v17_can_view_profile($id,$me))json_response(['message'=>'Bu hesap gizli.'],403);$type=($_GET['type']??'followers')==='following'?'following':'followers';$col=$type==='following'?'follower_user_id':'followed_user_id';$other=$type==='following'?'followed_user_id':'follower_user_id';$before=(int)($_GET['before_id']??PHP_INT_MAX);$rows=v17_query("SELECT u.* FROM follows f JOIN users u ON u.id=f.$other WHERE f.$col=? AND u.id<? ORDER BY u.id DESC LIMIT 51",[$id,$before])->fetchAll();$more=count($rows)>50;$rows=array_slice($rows,0,50);json_response(['people'=>array_map('v17_person',$rows),'followers'=>(int)v17_query('SELECT COUNT(*) FROM follows WHERE followed_user_id=?',[$id])->fetchColumn(),'following'=>(int)v17_query('SELECT COUNT(*) FROM follows WHERE follower_user_id=?',[$id])->fetchColumn(),'nextBeforeId'=>$more?(int)end($rows)['id']:null]);